CREATE TABLE feedback (
	id INTEGER NOT NULL, 
	listing_id VARCHAR NOT NULL, 
	verdict VARCHAR NOT NULL, 
	note TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE investment_metrics (
	listing_id VARCHAR NOT NULL, 
	gross_yield_pct FLOAT, 
	net_yield_pct FLOAT, 
	roi_pct FLOAT, 
	payback_years FLOAT, 
	estimated_monthly_rent FLOAT, 
	total_investment FLOAT, 
	investment_score FLOAT, 
	score_breakdown JSON, 
	computed_at DATETIME, 
	PRIMARY KEY (listing_id)
);
CREATE TABLE listings (
	id VARCHAR NOT NULL, 
	portal VARCHAR NOT NULL, 
	external_id VARCHAR NOT NULL, 
	url VARCHAR NOT NULL, 
	title TEXT, 
	price FLOAT, 
	area_m2 FLOAT, 
	price_per_m2 FLOAT, 
	rooms INTEGER, 
	bathrooms INTEGER, 
	floor VARCHAR, 
	condition VARCHAR, 
	latitude FLOAT, 
	longitude FLOAT, 
	district VARCHAR, 
	city VARCHAR, 
	zip_code VARCHAR, 
	description TEXT, 
	photo_urls JSON, 
	raw_html_hash VARCHAR, 
	price_history JSON, 
	first_seen_at DATETIME, 
	last_seen_at DATETIME, 
	is_active BOOLEAN, 
	PRIMARY KEY (id)
);
NO COBRAMOS COMISIÓN DE INTERMEDIACIÓN AL COMPRADOR. 

Excelente oportunidad de adquirir en propiedad esta espectacular vivienda muy bien distribuida ubicada en la encantadora localidad de Badalona, provincia de Barcelona.

La vivienda ofrece un lienzo en blanco para crear la vivienda de tus sueños.

Es una imponente vivienda con estructura sólida y un gran potencial, Dispone de amplias estancias, gran salón muy luminoso, amplia cocina amueblada, habitaciones con ventanas, lo que facilita la luminosidad y ventilación cruzada. 

Entre sus comodidades, una gran terraza donde poder invertir tu tiempo al aire libre desde la tranquilidad de tu hogar.

Su diseño espacioso y su distribución funcional ofrecen un sinfín de posibilidades para personalizarlo según tus gustos y necesidades. 

Se encuentra en una zona residencial muy apreciada, con todos los servicios necesarios a solo unos minutos. Además, la cercanía a la ciudad hace de esta vivienda una excelente opción para aquellos que buscan vivir en un entorno más relajado sin renunciar a las comodidades de la ciudad.

¡No pierdas esta oportunidad!

